def is_safe(board, row, col):
    # Check if the queen can attack any of the queens in the same row
    for i in range(len(board)):
        if board[i][col] == 1:
            return False

    # Check if the queen can attack any of the queens in the same column
    for i in range(len(board)):
        if board[row][i] == 1:
            return False

    # Check if the queen can attack any of the queens in the same diagonal (up-left to down-right)
    i, j = row, col
    while i >= 0 and j >= 0:
        if board[i][j] == 1:
            return False
        i -= 1
        j -= 1

